#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char *dup_cstr(const char *s) {
    size_t n = strlen(s) + 1;
    char *p = malloc(n);
    if (!p) exit(1);
    memcpy(p, s, n);
    return p;
}

static char *add_dec(const char *a, const char *b) {
    size_t la = strlen(a), lb = strlen(b);
    size_t l = (la > lb ? la : lb) + 1;
    char *r = malloc(l + 1);
    if (!r) exit(1);
    r[l] = '\0';

    int carry = 0;
    size_t ia = la, ib = lb, ir = l;
    while (ir > 0) {
        int da = (ia > 0) ? a[--ia] - '0' : 0;
        int db = (ib > 0) ? b[--ib] - '0' : 0;
        int sum = da + db + carry;
        r[--ir] = (char)('0' + (sum % 10));
        carry = sum / 10;
    }

    if (r[0] == '0') {
        memmove(r, r + 1, l);
    }
    return r;
}

static char *fib_dec(unsigned long long n) {
    char *x = dup_cstr("0");
    char *y = dup_cstr("1");
    for (unsigned long long i = 0; i < n; ++i) {
        char *z = add_dec(x, y);
        free(x);
        x = y;
        y = z;
    }
    free(y);
    return x;
}

int main(int argc, char **argv) {
    if (argc != 2) return 1;
    unsigned long long n = strtoull(argv[1], NULL, 10);
    char *ans = fib_dec(n);
    puts(ans);
    free(ans);
    return 0;
}
